 temp:{label:'Temperature',base:'C',special:true,units:{'Celsius (C)':1,'Fahrenheit (F)':1,'Kelvin (K)':1}},
 volume:{label:'Volume',base:'L',units:{'Millilitre (ml)':0.001,'Litre (L)':1,'Cubic metre':1000,'Teaspoon (US)':0.00492892,'Tablespoon (US)':0.0147868,'Cup (US)':0.236588,'Pint (US)':0.473176,'Gallon (US)':3.785411784,'Gallon (UK)':4.54609}},
 area:{label:'Area',base:'m2',units:{'Square metre':1,'Square kilometre':1000000,'Square foot':0.09290304,'Square yard':0.83612736,'Acre':4046.8564224,'Hectare':10000,'Marla':25.292852640000003,'Kanal':505.8570528000001}},
 speed:{label:'Speed',base:'m/s',units:{'Metres per second':1,'Kilometres per hour':0.277777778,'Miles per hour':0.44704,'Knot':0.514444444,'Foot per second':0.3048}},
 data:{label:'Data',base:'byte',units:{'Byte':1,'Kilobyte (KB)':1024,'Megabyte (MB)':1048576,'Gigabyte (GB)':1073741824,'Terabyte (TB)':1099511627776,'Bit':0.125}}
};
var kind=document.getElementById('kind'),ua=document.getElementById('ua'),ub=document.getElementById('ub'),
A=document.getElementById('a'),B=document.getElementById('b'),note=document.getElementById('note');
Object.keys(DATA).forEach(function(k){var o=document.createElement('option');o.value=k;o.textContent=DATA[k].label;kind.appendChild(o);});
function fillUnits(){
  var d=DATA[kind.value],names=Object.keys(d.units);
  ua.innerHTML='';ub.innerHTML='';
  names.forEach(function(n){
    var o1=document.createElement('option');o1.value=n;o1.textContent=n;ua.appendChild(o1);
    var o2=document.createElement('option');o2.value=n;o2.textContent=n;ub.appendChild(o2);
  });
  ua.selectedIndex=0;ub.selectedIndex=Math.min(1,names.length-1);
}
function toBase(v,unit,d){
  if(!d.special){return v*d.units[unit];}
  if(unit.indexOf('Fahrenheit')===0){return (v-32)*5/9;}
  if(unit.indexOf('Kelvin')===0){return v-273.15;}
  return v;
}
function fromBase(v,unit,d){
  if(!d.special){return v/d.units[unit];}
  if(unit.indexOf('Fahrenheit')===0){return v*9/5+32;}
  if(unit.indexOf('Kelvin')===0){return v+273.15;}
  return v;
}
function tidy(x){
  if(!isFinite(x))return '0';
  var abs=Math.abs(x);
  if(abs!==0&&(abs<0.000001||abs>=1e15)){return x.toExponential(6);}
  return String(Math.round(x*1e8)/1e8);
}
function convert(){
  var d=DATA[kind.value],v=parseFloat(A.value);
  if(isNaN(v)){B.value='';note.textContent='Enter a number to convert.';return;}
  var res=fromBase(toBase(v,ua.value,d),ub.value,d);
  B.value=tidy(res);
  note.textContent=v+' '+ua.value+' equals '+tidy(res)+' '+ub.value+'.';
  var box=document.getElementById('quick');box.innerHTML='';
  Object.keys(d.units).forEach(function(n){
    if(n===ua.value)return;
    var r=fromBase(toBase(v,ua.value,d),n,d);
    var el=document.createElement('div');
    el.innerHTML='<b>'+tidy(r)+'</b><br>'+n;
    box.appendChild(el);
  });
  WT.resize();
}
kind.addEventListener('change',function(){fillUnits();convert();});
[ua,ub].forEach(function(el){el.addEventListener('change',convert);});
A.addEventListener('input',convert);
document.getElementById('swap').addEventListener('click',function(){
  var t=ua.selectedIndex;ua.selectedIndex=ub.selectedIndex;ub.selectedIndex=t;convert();
});
document.getElementById('copy').addEventListener('click',function(){
  var ok=WT.copy(B.value);note.textContent=ok?'Result copied to clipboard.':'Copy failed, select the number instead.';
});
fillUnits();convert();
